:root {
  /* Colors */
  --color-onyx-canvas: #010314;
  --color-carbon-panel: #0b0d1c;
  --color-frosted-tile: #ffffff0f;
  --color-paper-ink: #ffffffe6;
  --color-fog-caption: #ffffff99;
  --color-ash-label: #ffffff80;
  --color-pewter-meta: #8e8fa0;
  --color-iron-border: #1d1f2e;
  --color-chalk-fill: #ffffff;
  --color-lilac-haze: #bea7ff1a;
  --color-iris-badge: #6633ee;
  --color-amethyst-signal: #8e64ff;
  --color-mint-pulse: #3ddc97;

  /* Typography — Font Families */
  --font-roobert: "Roobert", "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.2;
  --tracking-small: 0.4px;
  --text-caption: 12px;
  --leading-caption: 1.2;
  --tracking-caption: -0.12px;
  --text-body-sm: 12.8px;
  --leading-body-sm: 1.4;
  --tracking-body-sm: 0px;
  --text-body: 14.4px;
  --leading-body: 1.45;
  --tracking-body: 0px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: -0.32px;
  --text-subheading: 24px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 29.6px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.2;
  --tracking-heading: -0.4px;
  --text-display: 56px;
  --leading-display: 1.2;
  --tracking-display: -1.12px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-section-gap: 80px;
  --layout-card-padding: 24px;
  --layout-element-gap: 10px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-3xl: 24px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-buttons: 100px;
  --radius-pills: 100px;
  --radius-nav: 20px;
  --radius-sections: 24px;
  --radius-cards: 16px;
  --radius-images: 8px;
  --radius-inputs: 6px;
  --radius-small-cards: 4px;
  --radius-inner-tiles: 4px;
  --radius-badges: 4px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.05) 0px 0px 0px 2px, rgba(255, 255, 255, 0.1) 0px 0px 0px 1px, rgba(255, 255, 255, 0.5) 0px 0.5px 0px 0px inset;
  --shadow-subtle-2: rgba(190, 167, 255, 0.12) 0px 0px 0px 1px inset;
  --shadow-sm: rgba(0, 0, 0, 0.3) 0px 2px 8px 0px;
  --shadow-md: rgba(0, 0, 0, 0.34) 0px 0.36px 1.52px -1.5px, rgba(0, 0, 0, 0.29) 0px 1.37px 5.77px -3px, rgba(0, 0, 0, 0.04) 0px 6px 25.2px -4.5px, rgba(141, 99, 255, 0.2) 0px 2px 15px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.25) -7px 10px 18.6px 0px, rgba(0, 0, 0, 0.17) -2px 2px 4px 0px, rgba(0, 0, 0, 0.3) -2px 4px 34.5px 0px;

  /* Surfaces */
  --surface-onyx-canvas: #010314;
  --surface-carbon-panel: #0b0d1c;
  --surface-frosted-tile: #ffffff0f;
  --surface-lilac-haze: #bea7ff1a;
  --surface-chalk-fill: #ffffff;
}

